function validate([weights, k]) {
  if (!Array.isArray(weights) || weights.length < 1 || weights.length > 100000) return 'weights needs 1 to 10^5 values.';
  if (weights.some(w => !Number.isInteger(w) || w < 1 || w > 1000000000)) return 'Each weight is an integer from 1 to 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > weights.length) return 'k is between 1 and weights.length.';
  return null;
}

