function putMarbles(weights, k) {
  const pairs = [];
  for (let i = 0; i + 1 < weights.length; i++) {
    pairs.push(weights[i] + weights[i + 1]);
  }
  pairs.sort((a, b) => a - b);

  let difference = 0;
  for (let i = 0; i < k - 1; i++) {
    const largest = pairs[pairs.length - 1 - i];
    const smallest = pairs[i];
    difference += largest - smallest;
  }
  return difference;
}

