function putMarbles(weights, k) {
  const n = weights.length;
  let low = Infinity, high = -Infinity;
  // Try every way to cut the row: the bag starting at `start` ends at `end`.
  const place = (start, bagsLeft, score) => {
    if (bagsLeft === 1) {
      const total = score + weights[start] + weights[n - 1];
      low = Math.min(low, total);
      high = Math.max(high, total);
      return;
    }
    for (let end = start; end <= n - bagsLeft; end++) place(end + 1, bagsLeft - 1, score + weights[start] + weights[end]);
  };
  place(0, k, 0);
  return high - low;
}

