function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const k = 1 + Math.floor(rand() * n);
  const top = size === 'large' || rand() < 0.2 ? 1000000000 : 1 + Math.floor(rand() * 10);
  const weights = Array.from({ length: n }, () => 1 + Math.floor(rand() * top));
  return [weights, k];
}
